    <script>
        const accountShell = document.querySelector('[data-account-shell]');
        const accountSidebar = document.querySelector('[data-account-sidebar]');
        const accountBackdrop = document.querySelector('[data-account-backdrop]');
        const setAccountMenu = (open) => { accountSidebar?.classList.toggle('-translate-x-full', !open); accountSidebar?.classList.toggle('translate-x-0', open); accountBackdrop?.classList.toggle('hidden', !open); accountBackdrop?.classList.toggle('opacity-0', !open); accountBackdrop?.classList.toggle('opacity-100', open); document.body.classList.toggle('overflow-hidden', open); };
        document.querySelector('[data-account-open]')?.addEventListener('click', () => setAccountMenu(true)); document.querySelector('[data-account-close]')?.addEventListener('click', () => setAccountMenu(false)); accountBackdrop?.addEventListener('click', () => setAccountMenu(false));
        const accountThemeKey = 'travelconnect-dashboard-theme'; const accountDark = localStorage.getItem(accountThemeKey) === 'dark'; accountShell?.classList.toggle('dashboard-dark', accountDark); document.querySelector('[data-account-theme]')?.addEventListener('click', () => { const dark = !accountShell.classList.contains('dashboard-dark'); accountShell.classList.toggle('dashboard-dark', dark); localStorage.setItem(accountThemeKey, dark ? 'dark' : 'light'); });
        const accountCollapseKey = 'travelconnect-account-collapsed'; const setCollapsed = (collapsed) => { accountShell?.classList.toggle('account-collapsed', collapsed); localStorage.setItem(accountCollapseKey, collapsed ? 'true' : 'false'); }; setCollapsed(localStorage.getItem(accountCollapseKey) === 'true'); document.querySelector('[data-account-collapse]')?.addEventListener('click', () => setCollapsed(true)); document.querySelector('[data-account-expand]')?.addEventListener('click', () => setCollapsed(false));
            const profileTrigger = document.querySelector('[data-profile-trigger]'); const profileDropdown = document.querySelector('[data-profile-dropdown]'); profileTrigger?.addEventListener('click', () => { const open = profileTrigger.getAttribute('aria-expanded') === 'true'; profileTrigger.setAttribute('aria-expanded', String(!open)); profileDropdown?.classList.toggle('hidden', open); }); document.addEventListener('click', (event) => { if (!event.target.closest('[data-profile-menu]')) { profileTrigger?.setAttribute('aria-expanded', 'false'); profileDropdown?.classList.add('hidden'); } });
    </script>
